def solve_arc(grid_in):
    """Transform grid according to the folding rule"""
    rows = len(grid_in)
    cols = len(grid_in[0])

    # Output grid
    result = [[0]*cols for _ in range(rows)]

    # Upper region: rows 0-3
    # Band region: rows 5-8 (input); these disappear in output
    # Lower region: rows 10-13 (input)

    # Copy upper to output rows 0-3 (with 8s added)
    for r in range(4):  # upper rows 0-3
        for c in range(cols):
            if grid_in[r][c] == 2:
                # Add 8 at columns [0,6,12,18] where upper has 2
                if c in [0, 6, 12, 18] and grid_in[r][c] == 2:
                    result[r][c] = 8
                else:
                    result[r][c] = 2

    # Add band gap row (row 4 stays empty)
    # Shift upper into band (rows 5-8)
    for r in range(4):  # input upper rows 0-3 fold to output rows 5-8
        for c in range(cols):
            if c in [0, 6, 12, 18] and grid_in[r][c] == 2:
                result[5+r][c] = 8
            elif c in [0, 6, 12, 18]:
                result[5+r][c] = 2
            elif grid_in[r][c] == 2:
                result[5+r][c] = 2  # copy all other 2s

    # Band gap row (row 9 stays empty)

    # Lower region: rows 10-13 to output rows 10-13 (with 8s)
    for r in range(10, 14):  # lower rows 10-13
        for c in range(cols):
            if grid_in[r][c] == 2 and c in [0, 6, 12, 18]:
                result[r][c] = 8
            elif c in [0, 6, 12, 18]:
                result[r][c] = 2
            else:
                result[r][c] = 0

    # Band gap row (row 14 stays empty)

    # Copy lower to output rows 15-18 (with 8s)
    for r in range(10, 14):  # lower rows 10-13 fold to output rows 15-18
        for c in range(cols):
            if grid_in[r][c] == 2 and c in [0, 6, 12, 18]:
                result[15+(r-10)][c] = 8
            elif c in [0, 6, 12, 18]:
                result[15+(r-10)][c] = 2
            else:
                result[15+(r-10)][c] = 0

    return result

